427	// Ask the owner to add a repo Actions secret a task declares in `required_secrets`
428	// but the repo has not configured. The wiring converge stamps every declared name
429	// into the scheduler workflow, so by the time this runs the value is either in the
430	// environment or genuinely unset — no separate probe needed.
431	//
432	// This is the adoption interview's posture, not a gate: nothing fails, no check
433	// fires, and the task that needs the secret simply doesn't work until someone adds
434	// it. One open issue per repo (matched by exact title) so an unconfigured secret
435	// costs one issue, not one per night. Exported for the tests.
436	export const SECRETS_ISSUE_TITLE = 'Claudinite: configure required Actions secrets';
437	
438	export function unconfiguredSecrets(declared, env) {
439	  return (declared ?? []).filter((name) => !env[name]);
440	}
441	
442	async function askForSecrets(token, repo, names) {
443	  const q = encodeURIComponent(`repo:${repo} in:title "${SECRETS_ISSUE_TITLE}" state:open`);
444	  const { json } = await gh(token, `/search/issues?q=${q}&per_page=10`);
445	  if ((json?.items ?? []).some((i) => (i.title ?? '').trim() === SECRETS_ISSUE_TITLE)) return false;
446	  const body = [
447	    'A scheduled task in this repo declares a repo **Actions secret** that is not configured yet.',
448	    'Until it is, that task cannot do its work — everything else keeps running normally.',
449	    '',
450	    ...names.map((n) => `- \`${n}\``),
451	    '',
452	    `Add each one at https://github.com/${repo}/settings/secrets/actions, then close this issue.`,
453	  ].join('\n');
454	  await gh(token, `/repos/${repo}/issues`, { method: 'POST', body: { title: SECRETS_ISSUE_TITLE, body } });
455	  return true;
456	}
