458	// Arm native auto-merge on a PR (by node id) via the GraphQL mutation — the REST
459	// `PUT /merge` would merge NOW, ignoring pending checks; this waits for them.
460	async function enableAutoMerge(token, pullRequestId) {
461	  const query = 'mutation($id:ID!){enablePullRequestAutoMerge(input:{pullRequestId:$id,mergeMethod:SQUASH}){pullRequest{id}}}';
462	  const res = await fetch(`${API}/graphql`, {
463	    method: 'POST',
464	    headers: { authorization: `Bearer ${token}`, 'content-type': 'application/json' },
465	    body: JSON.stringify({ query, variables: { id: pullRequestId } }),
466	  });
467	  const json = await res.json().catch(() => null);
468	  if (json?.errors?.length) throw new Error(json.errors[0].message);
469	}
